setup by making the RestClient final and keeping the work-key guard and JSON headers in place.","tree":{"sha":"c3165579ca7139c052b1b0b90d7bb49ea130efbc","url":"https://api.github.com/repos/grifftatarsky/akira-platform/git/trees/c3165579ca7139c052b1b0b90d7bb49ea130efbc"},"url":"https://api.github.com/repos/grifftatarsky/akira-platform/git/commits/915b816f7626d9c9e3fef5d4ab47ff182431f1aa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/52219673?v=4","events_url":"https://api.github.com/users/grifftatarsky/events{/privacy}","followers_url":"https://api.github.com/users/grifftatarsky/followers","following_url":"https://api.github.com/users/grifftatarsky/following{/other_user}","gists_url":"https://api.github.com/users/grifftatarsky/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/grifftatarsky","id":52219673,"login":"grifftatarsky","node_id":"MDQ6VXNlcjUyMjE5Njcz","organizations_url":"https://api.github.com/users/grifftatarsky/orgs","received_events_url":"https://api.github.com/users/grifftatarsky/received_events","repos_url":"https://api.github.com/users/grifftatarsky/repos","site_admin":false,"starred_url":"https://api.github.com/users/grifftatarsky/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/grifftatarsky/subscriptions","type":"User","url":"https://api.github.com/users/grifftatarsky","user_view_type":"public"},"html_url":"https://github.com/grifftatarsky/akira-platform/commit/915b816f7626d9c9e3fef5d4ab47ff182431f1aa","node_id":"C_kwDONOaLmdoAKDkxNWI4MTZmNzYyNmQ5YzllM2ZlZjVkNGFiNDdmZjE4MjQzMWYxYWE","parents":[{"html_url":"https://github.com/grifftatarsky/akira-platform/commit/d6cf32fec9163624c73402beaf7f954d774eaf02","sha":"d6cf32fec9163624c73402beaf7f954d774eaf02","url":"https://api.github.com/repos/grifftatarsky/akira-platform/commits/d6cf32fec9163624c73402beaf7f954d774eaf02"}],"sha":"915b816f7626d