rl":"https://api.github.com/users/web-flow/repos","site_admin":false,"starred_url":"https://api.github.com/users/web-flow/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/web-flow/subscriptions","type":"User","url":"https://api.github.com/users/web-flow","user_view_type":"public"},"html_url":"https://github.com/prompt-edu/prompt/commit/414e86e0ecffa85cf7b5573e7fd7f65088272488","node_id":"C_kwDONRrZeNoAKDQxNGU4NmUwZWNmZmE4NWNmN2I1NTczZTdmZDdmNjUwODgyNzI0ODg","parents":[{"html_url":"https://github.com/prompt-edu/prompt/commit/4a5b20b3aad8f9a546ad1bbf6336b797c10b5489","sha":"4a5b20b3aad8f9a546ad1bbf6336b797c10b5489","url":"https://api.github.com/repos/prompt-edu/prompt/commits/4a5b20b3aad8f9a546ad1bbf6336b797c10b5489"}],"sha":"414e86e0ecffa85cf7b5573e7fd7f65088272488","url":"https://api.github.com/repos/prompt-edu/prompt/commits/414e86e0ecffa85cf7b5573e7fd7f65088272488"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/in/2740?v=4","events_url":"https://api.github.com/users/renovate%5Bbot%5D/events{/privacy}","followers_url":"https://api.github.com/users/renovate%5Bbot%5D/followers","following_url":"https://api.github.com/users/renovate%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/renovate%5Bbot%5D/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/apps/renovate","id":29139614,"login":"renovate[bot]","node_id":"MDM6Qm90MjkxMzk2MTQ=","organizations_url":"https://api.github.com/users/renovate%5Bbot%5D/orgs","received_events_url":"https://api.github.com/users/renovate%5Bbot%5D/received_events","repos_url":"https://api.github.com/users/renovate%5Bbot%5D/repos","site_admin":false,"starred_url":"https://api.github.com/users/renovate%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/renovate%5Bbot%5D/subscriptions","type":"Bot","url":"https://api.github.com/users/renovate%5Bbot%5D","user_view_type":"public"},"comments_url":"https://api.github.com/repos/prompt-ed